/**
 * Unit tests for DateTimeZone.forOffsetHoursMinutes
 */
public class DateTimeZone_forOffsetHoursMinutes_TriageGen1Test {

    @Test
    public void testForOffsetHoursMinutes_UTC() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 0);
        assertEquals(DateTimeZone.UTC, zone);
    }

    @Test
    public void testForOffsetHoursMinutes_PositiveOffset() {
        // Test +5:30
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 30);
        int expectedOffsetMillis = (5 * 60 + 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeOffset() {
        // Test -5:30
        // Note: The logic handles negative hours by subtracting minutes from the negative hour total
        // hoursInMinutes = -300. minutesOffset = -300 + (-30) = -330? 
        // Actually, let's trace: hoursInMinutes = -300. since < 0, minutesOffset = FieldUtils.safeAdd(-300, -30) = -330.
        // Wait, the code logic: if (hoursInMinutes < 0) { minutesOffset = FieldUtils.safeAdd(hoursInMinutes, -minutesOffset); }
        // If hoursOffset = -5, minutesOffset = 30:
        // hoursInMinutes = -300. 
        // minutesOffset = -300 + (-30) = -330. 
        // result = -330 * 60000 = -19800000 (which is -5:30)
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 30);
        int expectedOffsetMillis = (-5 * 60 - 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_MinutesTooLow() {
        try {
            DateTimeZone.forOffsetHoursMinutes(5, -1);
            fail("Expected IllegalArgumentException for negative minutes");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Minutes out of range"));
        }
    }

    @Test
    public void testForOffsetHoursMinutes_MinutesTooHigh() {
        try {
            DateTimeZone.forOffsetHoursMinutes(5, 60);
            fail("Expected IllegalArgumentException for minutes > 59");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Minutes out of range"));
        }
    }

    @Test
    public void testForOffsetHoursMinutes_ArithmeticOverflow() {
        // Attempt to trigger ArithmeticException in FieldUtils
        // Integer.MAX_VALUE is approx 2*10^9. 
        // hoursOffset * 60 or offset * MILLIS_PER_MINUTE might overflow.
        try {
            DateTimeZone.forOffsetHoursMinutes(Integer.MAX_VALUE, 30);
            fail("Expected IllegalArgumentException due to overflow");
        } catch (IllegalArgumentException e) {
            assertEquals("Offset is too large", e.getMessage());
        }
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeHoursLarge() {
        // Test -12:00
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-12, 0);
        int expectedOffsetMillis = -12 * 60 * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_ZeroHoursPositiveMinutes() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 45);
        int expectedOffsetMillis = 45 * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }
}
